    /// <summary>逐分组比较：引用相同的分组直接跳过。</summary>
    static StyleDifference DiffGroups(ComputedStyle a, ComputedStyle b)
    {
        var d = StyleDifference.None;
        if (!ReferenceEquals(a.BoxGroup, b.BoxGroup))
        {
            var x = a.BoxGroup;
            var y = b.BoxGroup;
            if (x.Display != y.Display) d |= StyleDifference.Structure;
            if (x.BoxSizing != y.BoxSizing) d |= StyleDifference.Layout;
            if (!x.Width.Equals(y.Width)) d |= StyleDifference.Layout;
            if (!x.Height.Equals(y.Height)) d |= StyleDifference.Layout;
            if (!x.MinWidth.Equals(y.MinWidth)) d |= StyleDifference.Layout;
            if (!x.MinHeight.Equals(y.MinHeight)) d |= StyleDifference.Layout;
            if (!x.MaxWidth.Equals(y.MaxWidth)) d |= StyleDifference.Layout;
            if (!x.MaxHeight.Equals(y.MaxHeight)) d |= StyleDifference.Layout;
            if (!x.MarginTop.Equals(y.MarginTop)) d |= StyleDifference.Layout;
            if (!x.MarginRight.Equals(y.MarginRight)) d |= StyleDifference.Layout;
            if (!x.MarginBottom.Equals(y.MarginBottom)) d |= StyleDifference.Layout;
            if (!x.MarginLeft.Equals(y.MarginLeft)) d |= StyleDifference.Layout;
            if (!x.PaddingTop.Equals(y.PaddingTop)) d |= StyleDifference.Layout;
            if (!x.PaddingRight.Equals(y.PaddingRight)) d |= StyleDifference.Layout;
            if (!x.PaddingBottom.Equals(y.PaddingBottom)) d |= StyleDifference.Layout;
            if (!x.PaddingLeft.Equals(y.PaddingLeft)) d |= StyleDifference.Layout;
            if (x.OverflowX != y.OverflowX) d |= StyleDifference.Structure;
            if (x.OverflowY != y.OverflowY) d |= StyleDifference.Structure;
            if (!x.AspectRatio.Equals(y.AspectRatio)) d |= StyleDifference.Layout;
        }
        if (!ReferenceEquals(a.PositionGroup, b.PositionGroup))
        {
            var x = a.PositionGroup;
            var y = b.PositionGroup;
            if (x.Position != y.Position) d |= StyleDifference.Structure;
            if (!x.Top.Equals(y.Top)) d |= StyleDifference.Layout;
            if (!x.Right.Equals(y.Right)) d |= StyleDifference.Layout;
            if (!x.Bottom.Equals(y.Bottom)) d |= StyleDifference.Layout;
            if (!x.Left.Equals(y.Left)) d |= StyleDifference.Layout;
            if (!x.ZIndex.Equals(y.ZIndex)) d |= StyleDifference.Structure;
        }
        if (!ReferenceEquals(a.FlexGroup, b.FlexGroup))
        {
            var x = a.FlexGroup;
            var y = b.FlexGroup;
            if (x.FlexDirection != y.FlexDirection) d |= StyleDifference.Layout;
            if (x.FlexWrap != y.FlexWrap) d |= StyleDifference.Layout;
            if (x.FlexGrow != y.FlexGrow) d |= StyleDifference.Layout;
            if (x.FlexShrink != y.FlexShrink) d |= StyleDifference.Layout;
            if (!x.FlexBasis.Equals(y.FlexBasis)) d |= StyleDifference.Layout;
            if (x.JustifyContent != y.JustifyContent) d |= StyleDifference.Layout;
            if (x.AlignItems != y.AlignItems) d |= StyleDifference.Layout;
            if (x.AlignSelf != y.AlignSelf) d |= StyleDifference.Layout;
            if (x.AlignContent != y.AlignContent) d |= StyleDifference.Layout;
            if (!x.RowGap.Equals(y.RowGap)) d |= StyleDifference.Layout;
            if (!x.ColumnGap.Equals(y.ColumnGap)) d |= StyleDifference.Layout;
            if (x.Order != y.Order) d |= StyleDifference.Layout;
            if (x.JustifyItems != y.JustifyItems) d |= StyleDifference.Layout;
            if (x.JustifySelf != y.JustifySelf) d |= StyleDifference.Layout;
            if (!object.Equals(x.GridTemplateColumns, y.GridTemplateColumns)) d |= StyleDifference.Layout;
            if (!object.Equals(x.GridTemplateRows, y.GridTemplateRows)) d |= StyleDifference.Layout;
            if (!object.Equals(x.GridTemplateAreas, y.GridTemplateAreas)) d |= StyleDifference.Layout;
            if (!object.Equals(x.GridAutoColumns, y.GridAutoColumns)) d |= StyleDifference.Layout;
            if (!object.Equals(x.GridAutoRows, y.GridAutoRows)) d |= StyleDifference.Layout;
            if (x.GridAutoFlow != y.GridAutoFlow) d |= StyleDifference.Layout;
            if (x.GridRowStart != y.GridRowStart) d |= StyleDifference.Layout;
            if (x.GridRowEnd != y.GridRowEnd) d |= StyleDifference.Layout;
            if (x.GridColumnStart != y.GridColumnStart) d |= StyleDifference.Layout;
            if (x.GridColumnEnd != y.GridColumnEnd) d |= StyleDifference.Layout;
        }
        if (!ReferenceEquals(a.BorderGroup, b.BorderGroup))
        {
            var x = a.BorderGroup;
            var y = b.BorderGroup;
            if (x.BorderTopWidth != y.BorderTopWidth) d |= StyleDifference.Layout;
            if (x.BorderRightWidth != y.BorderRightWidth) d |= StyleDifference.Layout;
            if (x.BorderBottomWidth != y.BorderBottomWidth) d |= StyleDifference.Layout;
            if (x.BorderLeftWidth != y.BorderLeftWidth) d |= StyleDifference.Layout;
            if (x.BorderTopStyle != y.BorderTopStyle) d |= StyleDifference.Paint;
            if (x.BorderRightStyle != y.BorderRightStyle) d |= StyleDifference.Paint;
            if (x.BorderBottomStyle != y.BorderBottomStyle) d |= StyleDifference.Paint;
            if (x.BorderLeftStyle != y.BorderLeftStyle) d |= StyleDifference.Paint;
            if (!x.BorderTopColor.Equals(y.BorderTopColor)) d |= StyleDifference.Paint;
            if (!x.BorderRightColor.Equals(y.BorderRightColor)) d |= StyleDifference.Paint;
            if (!x.BorderBottomColor.Equals(y.BorderBottomColor)) d |= StyleDifference.Paint;
            if (!x.BorderLeftColor.Equals(y.BorderLeftColor)) d |= StyleDifference.Paint;
            if (!x.BorderTopLeftRadius.Equals(y.BorderTopLeftRadius)) d |= StyleDifference.Paint;
            if (!x.BorderTopRightRadius.Equals(y.BorderTopRightRadius)) d |= StyleDifference.Paint;
            if (!x.BorderBottomRightRadius.Equals(y.BorderBottomRightRadius)) d |= StyleDifference.Paint;
            if (!x.BorderBottomLeftRadius.Equals(y.BorderBottomLeftRadius)) d |= StyleDifference.Paint;
        }
        if (!ReferenceEquals(a.BackgroundGroup, b.BackgroundGroup))
        {
            var x = a.BackgroundGroup;
            var y = b.BackgroundGroup;
            if (!x.BackgroundColor.Equals(y.BackgroundColor)) d |= StyleDifference.Paint;
            if (!object.Equals(x.BackgroundImage, y.BackgroundImage)) d |= StyleDifference.Paint;
        }
        if (!ReferenceEquals(a.EffectsGroup, b.EffectsGroup))
        {
            var x = a.EffectsGroup;
            var y = b.EffectsGroup;
            if (x.Opacity != y.Opacity) d |= StyleDifference.Composite;
            if (!object.Equals(x.BoxShadow, y.BoxShadow)) d |= StyleDifference.Paint;
            if (x.TextOverflow != y.TextOverflow) d |= StyleDifference.Paint;
            if (x.OutlineWidth != y.OutlineWidth) d |= StyleDifference.Paint;
            if (x.OutlineStyle != y.OutlineStyle) d |= StyleDifference.Paint;
            if (!x.OutlineColor.Equals(y.OutlineColor)) d |= StyleDifference.Paint;
            if (!x.OutlineOffset.Equals(y.OutlineOffset)) d |= StyleDifference.Paint;
            if (x.ObjectFit != y.ObjectFit) d |= StyleDifference.Paint;
            if (!x.ObjectPosition.Equals(y.ObjectPosition)) d |= StyleDifference.Paint;
        }
        if (!ReferenceEquals(a.FontGroup, b.FontGroup))
        {
            var x = a.FontGroup;
            var y = b.FontGroup;
            if (!object.Equals(x.FontFamily, y.FontFamily)) d |= StyleDifference.Layout;
            if (x.FontSize != y.FontSize) d |= StyleDifference.Layout;
            if (x.FontWeight != y.FontWeight) d |= StyleDifference.Layout;
            if (x.FontStyle != y.FontStyle) d |= StyleDifference.Layout;
            if (x.FontStretch != y.FontStretch) d |= StyleDifference.Layout;
            if (!x.LineHeight.Equals(y.LineHeight)) d |= StyleDifference.Layout;
        }
        if (!ReferenceEquals(a.TextGroup, b.TextGroup))
        {
            var x = a.TextGroup;
            var y = b.TextGroup;
            if (!x.Color.Equals(y.Color)) d |= StyleDifference.Paint;
            if (x.TextAlign != y.TextAlign) d |= StyleDifference.Layout;
            if (x.WhiteSpace != y.WhiteSpace) d |= StyleDifference.Layout;
            if (x.WordBreak != y.WordBreak) d |= StyleDifference.Layout;
            if (x.OverflowWrap != y.OverflowWrap) d |= StyleDifference.Layout;
            if (x.Visibility != y.Visibility) d |= StyleDifference.Paint;
            if (x.ImageRendering != y.ImageRendering) d |= StyleDifference.Paint;
        }
        if (!ReferenceEquals(a.InteractionGroup, b.InteractionGroup))
        {
            var x = a.InteractionGroup;
            var y = b.InteractionGroup;
            if (x.Cursor != y.Cursor) d |= StyleDifference.Behavior;
            if (x.PointerEvents != y.PointerEvents) d |= StyleDifference.Behavior;
        }
        return d;
    }

    /// <summary>长属性计算值的 CSS 文本（DevTools 的 getComputedStyle）；简写返回空串。</summary>
    public string GetPropertyValueText(CssPropertyId id)
    {
        switch (id)
        {
            case CssPropertyId.Display: { var x = BoxGroup.Display; return KeywordTables.CssDisplay.NameOf((int)x); }
            case CssPropertyId.BoxSizing: { var x = BoxGroup.BoxSizing; return KeywordTables.CssBoxSizing.NameOf((int)x); }
            case CssPropertyId.Width: { var x = BoxGroup.Width; return x.ToString(); }
            case CssPropertyId.Height: { var x = BoxGroup.Height; return x.ToString(); }
            case CssPropertyId.MinWidth: { var x = BoxGroup.MinWidth; return x.ToString(); }
            case CssPropertyId.MinHeight: { var x = BoxGroup.MinHeight; return x.ToString(); }
            case CssPropertyId.MaxWidth: { var x = BoxGroup.MaxWidth; return x.ToString(); }
            case CssPropertyId.MaxHeight: { var x = BoxGroup.MaxHeight; return x.ToString(); }
            case CssPropertyId.MarginTop: { var x = BoxGroup.MarginTop; return x.ToString(); }
            case CssPropertyId.MarginRight: { var x = BoxGroup.MarginRight; return x.ToString(); }
            case CssPropertyId.MarginBottom: { var x = BoxGroup.MarginBottom; return x.ToString(); }
            case CssPropertyId.MarginLeft: { var x = BoxGroup.MarginLeft; return x.ToString(); }
            case CssPropertyId.PaddingTop: { var x = BoxGroup.PaddingTop; return x.ToString(); }
            case CssPropertyId.PaddingRight: { var x = BoxGroup.PaddingRight; return x.ToString(); }
            case CssPropertyId.PaddingBottom: { var x = BoxGroup.PaddingBottom; return x.ToString(); }
            case CssPropertyId.PaddingLeft: { var x = BoxGroup.PaddingLeft; return x.ToString(); }
            case CssPropertyId.OverflowX: { var x = BoxGroup.OverflowX; return KeywordTables.CssOverflow.NameOf((int)x); }
            case CssPropertyId.OverflowY: { var x = BoxGroup.OverflowY; return KeywordTables.CssOverflow.NameOf((int)x); }
            case CssPropertyId.AspectRatio: { var x = BoxGroup.AspectRatio; return x.ToString(); }
            case CssPropertyId.Position: { var x = PositionGroup.Position; return KeywordTables.CssPosition.NameOf((int)x); }
            case CssPropertyId.Top: { var x = PositionGroup.Top; return x.ToString(); }
            case CssPropertyId.Right: { var x = PositionGroup.Right; return x.ToString(); }
